sp_widget.client_script:
api.controller = function($scope, $timeout, $window) {
  // Everything that happens in the browser: layout, tabs, lists, search, review buttons, uploads. No Link function.
  var c = this;
  $scope.c = c;
  c.build = '21';   // must match the "server build" at the bottom of the page

  var BLEED = true;   // true: the dashboard uses the whole window width. false: it stays inside the portal container
  var MAX_BYTES = 3 * 1024 * 1024;
  var MAX_FILES = 10;
  var ALLOWED = ['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'application/pdf'];

  var TEAM_LISTS = [
    { key: 'need', label: 'Missing or rejected' },
    { key: 'expiring', label: 'Expiring soon' },
    { key: 'stale', label: 'Stale (expired)' },
    { key: 'noOwner', label: 'Without owner' },
    { key: 'uncovered', label: 'Services not covered' }
  ];
  var MINE_LISTS = [
    { key: 'need', label: 'Need evidence' },
    { key: 'expiring', label: 'Expiring soon' },
    { key: 'stale', label: 'Stale (expired)' }
  ];
  var EMPTY_TEXT = {
    need: 'Nothing is missing or rejected. Well done.',
    expiring: 'Nothing expires soon.',
    stale: 'Nothing is stale.',
    noOwner: 'Every service and control has an owner.',
    uncovered: 'Every service has approved evidence.'
  };

  /* ---------- remembered choices (this browser session only) ---------- */
  function remember(key, value) {
    try { $window.sessionStorage.setItem('cpm.' + key, JSON.stringify(value)); } catch (e) { /* storage unavailable: nothing is remembered */ }
  }
  function recall(key, fallback) {
    try {
      var raw = $window.sessionStorage.getItem('cpm.' + key);
      return raw === null ? fallback : JSON.parse(raw);
    } catch (e) { return fallback; }
  }

  /* ---------- state ---------- */
  c.label = {
    approved: 'Approved', expiring: 'Expiring soon', awaiting: 'Awaiting review',
    rejected: 'Rejected', missing: 'Needs evidence', expired: 'Expired', uncovered: 'Not covered'
  };
  c.riskLabel = { green: 'On track', yellow: 'Watch', red: 'Action needed', not_assessed: 'Not assessed' };

  var isAdmin = !!($scope.data && $scope.data.isAdmin);
  var tabs = isAdmin ? ['review', 'follow', 'all', 'mine'] : ['mine'];
  var savedTab = recall('tab', '');
  var savedSel = recall('sel', null);
  c.tab = tabs.indexOf(savedTab) > -1 ? savedTab : tabs[0];
  c.sel = savedSel || { team: 'need', mine: 'need' };   // selected list per follow-up block
  c.mineView = recall('mv', 'todo') === 'services' ? 'services' : 'todo';   // "My services": the to-do list or the service cards

  c.q = '';
  c.filter = 'all';
  c.filters = [
    { key: 'all', label: 'All' }, { key: 'red', label: 'Action needed' }, { key: 'yellow', label: 'Watch' },
    { key: 'green', label: 'On track' }, { key: 'not_assessed', label: 'Not assessed' }
  ];
  c.staged = {};     // chosen files per control
  c.busy = {};       // upload running, per control
  c.progress = {};   // Submit button text, per control
  c.msg = {};        // error under the upload area, per control
  c.working = {};    // review action running, per submission
  c.rejecting = {};  // reject box open, per submission
  c.comment = {};    // rejection reason, per submission
  c.opening = '';
  c.preview = null;
  c.exporting = false;
  c.syncing = false;
  c.toast = null;
  c.loading = 0;     // requests running (drives the loading bar)

  /* ---------- layout ---------- */

  // the stats guide: remembered, else open when there is room for three columns
  var savedCat = recall('cat', null);
  c.catOpen = savedCat === null ? false : savedCat;
  c.catQ = '';
  if (savedCat === null) {
    $timeout(function() {
      var frame = document.querySelector('.cpm-frame');
      if (frame && frame.clientWidth >= 1100) c.catOpen = true;
    });
  }
  c.toggleGuide = function() {
    c.catOpen = !c.catOpen;
    remember('cat', c.catOpen);
  };

  // the dashboard uses the whole window width and fills the height under its top edge:
  // the banner, the bars and the side columns stand still
  function fit() {
    var cq = document.querySelector('.cpm-cq');
    var frame = document.querySelector('.cpm-frame');
    if (!cq || !frame) return;
    cq.style.marginLeft = '';
    cq.style.width = '';
    frame.style.height = '';
    if (BLEED) {
      cq.style.marginLeft = (-cq.getBoundingClientRect().left) + 'px';
      cq.style.width = document.documentElement.clientWidth + 'px';
    }
    frame.classList.toggle('bleed', BLEED);
    var top = frame.getBoundingClientRect().top + ($window.pageYOffset || 0);
    frame.style.height = Math.max(560, $window.innerHeight - top - (BLEED ? 0 : 12)) + 'px';
  }
  $timeout(fit);
  $timeout(fit, 400);   // again once the portal has finished its own layout
  angular.element($window).on('resize', fit);

  /* ---------- server calls ---------- */

  // server data out of a response, or null
  function dataOf(response) {
    var d = response && response.data;
    return (d && typeof d === 'object' && d.serverBuild !== undefined) ? d : null;
  }

  // sends a request with the page parameters and returns the answer (page data untouched)
  function ask(extra) {
    var payload = angular.extend({}, ($scope.data || {}).params, extra || {});
    c.loading++;
    var done = function() { c.loading = Math.max(0, c.loading - 1); };
    var request = c.server.get(payload).then(dataOf);
    request.then(done, done);
    return request;
  }

  // like ask(), then replaces the page data
  function refresh(extra) {
    return ask(extra).then(function(fresh) {
      if (fresh) $scope.data = fresh;
      return fresh;
    });
  }

  c.dbg = function() {
    return (($scope.data || {}).params || {}).debug == '1' ? '&debug=1' : '';
  };

  c.openTarget = function(id) {
    if (id) $window.location.href = '?id=cpm&target=' + id + c.dbg();
  };

  /* ---------- messages at the top disappear by themselves ---------- */
  var HIDE_OK_MS = 6000;
  var HIDE_ERROR_MS = 10000;

  $scope.$watch(function() { return c.toast; }, function(t) {
    if (!t) return;
    $timeout(function() { if (c.toast === t) c.toast = null; }, t.type === 'error' ? HIDE_ERROR_MS : HIDE_OK_MS);
  });

  $scope.$watch(function() { return ($scope.data || {}).notice; }, function(n) {
    if (!n) return;
    $timeout(function() { if (($scope.data || {}).notice === n) $scope.data.notice = null; }, n.type === 'error' ? HIDE_ERROR_MS : HIDE_OK_MS);
  });

  /* ---------- stats guide ---------- */

  // the guide, built once with the numbers of this instance. "list" makes an entry open that list, "team" shows it to the team only
  function buildCatalog(rules) {
    rules = rules || {};
    var goal = rules.goal || 80;
    var yellow = rules.yellow || 50;
    var warn = rules.warning || 30;
    return [
      { title: 'Coverage', items: [
        { tone: 'ok', title: 'Services covered', text: 'A service with at least one valid approved evidence.',
          how: 'Covered ÷ all services in scope (team) or your services (owner). Assigned controls alone do not count.' },
        { tone: 'brand', title: 'Coverage ring', text: 'The ring in the banner.',
          how: 'Covered services ÷ total × 100. The white tick marks the goal (' + goal + '%).' }
      ] },
      { title: 'Control status', items: [
        { tone: 'ok', title: 'Approved', text: 'Evidence accepted and still valid.', how: 'Valid until the date shown on the control.' },
        { tone: 'watch', title: 'Expiring soon', list: 'expiring', text: 'Approved, ending within ' + warn + ' days.',
          how: 'You can send a renewal from ' + warn + ' days before the end date.' },
        { tone: 'review', title: 'In review', text: 'Submitted and waiting for the compliance team.', how: 'A valid approval stays approved while a renewal is reviewed.' },
        { tone: 'action', title: 'Rejected', list: 'need', text: 'The reviewer asked for a better proof.', how: 'Read the reason on the control, then upload again.' },
        { tone: 'idle', title: 'Needs evidence', list: 'need', text: 'No evidence has been sent yet.', how: 'The owner of the control uploads images or PDF files.' },
        { tone: 'action', title: 'Expired / stale', list: 'stale', text: 'The approval date has passed.', how: 'Counted as expired the same day, without waiting for the nightly job.' }
      ] },
      { title: 'Risk levels', items: [
        { tone: 'ok', title: 'On track', text: 'Share of approved controls of a service is ' + goal + '% or more.', how: 'Approved controls ÷ controls of the service.' },
        { tone: 'watch', title: 'Watch', text: 'Between ' + yellow + '% and ' + (goal - 1) + '%.' },
        { tone: 'action', title: 'Action needed', text: 'Below ' + yellow + '%.' },
        { tone: 'idle', title: 'Not assessed', text: 'The service has no control yet.' }
      ] },
      { title: 'Team views', team: true, items: [
        { tone: 'review', title: 'To review', team: true, text: 'Submissions waiting for a decision, oldest first.', how: 'Red after 5 days of waiting.' },
        { tone: 'idle', title: 'Without owner', list: 'noOwner', team: true, text: 'Controls with no owner, or on a CI with no owner in the CMDB.', how: 'Set "Owned by" in the CMDB, then use Refresh owners.' },
        { tone: 'idle', title: 'Services not covered', list: 'uncovered', team: true, text: 'Services in scope with no valid approved evidence.', how: 'Each row says whether controls are assigned.' },
        { tone: 'brand', title: 'Framework coverage', team: true, text: 'Services covered by at least one approved evidence of that framework.', how: 'Shown in the Frameworks card on the right.' },
        { tone: 'ok', title: 'Integrity sealed', team: true, text: 'An approval carries a fingerprint of its data and files.', how: '"Changed after approval" means something was modified since.' }
      ] },
      { title: 'Good to know', items: [
        { tone: 'brand', title: 'Approvals card', text: 'Decisions of the last 30 days.',
          how: 'Approval rate = approved ÷ (approved + rejected). Review time = submission to decision.' },
        { tone: 'brand', title: 'Who can upload', text: 'Only the owner of the control, never the reviewer.',
          how: 'Images (PNG, JPG, GIF, WEBP) or PDF, up to ' + (rules.maxMb || 3) + ' MB each and ' + (rules.maxFiles || 10) + ' files per submission.' },
        { tone: 'brand', title: 'Service composition', text: 'The components of a service come from the CMDB relationships.', how: 'The list valid on the approval day is stored with the evidence.' }
      ] }
    ];
  }
  c.catalog = buildCatalog(($scope.data || {}).rules);

  c.catMatch = function(e) {
    var q = (c.catQ || '').trim().toLowerCase();
    return !q || (e.title + ' ' + e.text + ' ' + (e.how || '')).toLowerCase().indexOf(q) > -1;
  };

  // a click on a guide entry opens the matching list
  c.jump = function(entry) {
    if (entry.list) c.go(isAdmin ? 'follow' : 'mine', entry.list);
  };

  /* ---------- "Controls by status" ring ---------- */
  var donutCache = { data: null, value: null };

  function computeDonut(d) {
    var part = d.isAdmin ? d.team : d.mine;
    var s = (part && part.kpi && part.kpi.states) || {};
    var parts = [
      { tone: 'ok', label: 'Approved', n: (s.approved || 0) - (s.expiring || 0) },
      { tone: 'watch', label: 'Expiring soon', n: s.expiring || 0 },
      { tone: 'review', label: 'In review', n: s.awaiting || 0 },
      { tone: 'action', label: 'Rejected or expired', n: (s.rejected || 0) + (s.expired || 0) },
      { tone: 'idle', label: 'Needs evidence', n: s.missing || 0 }
    ];
    var total = parts.reduce(function(sum, p) { return sum + p.n; }, 0);
    var used = 0;
    parts.forEach(function(p) {
      p.len = total ? p.n / total * 163.36 : 0;
      p.off = -used;
      p.pct = total ? Math.round(p.n / total * 100) : 0;
      used += p.len;
    });
    return { total: total, segs: parts };
  }

  c.donut = function() {
    var d = $scope.data || {};
    if (donutCache.data !== d) { donutCache.data = d; donutCache.value = computeDonut(d); }
    return donutCache.value;
  };

  /* ---------- banner ---------- */

  // ring value: company services covered (team) or my services covered (owner)
  c.hero = function() {
    var d = $scope.data || {};
    return d.isAdmin ? ((d.company && d.company.coveredPct) || 0) : ((d.mine && d.mine.kpi && d.mine.kpi.coveredPct) || 0);
  };

  // tick on the ring at the goal
  c.tick = function() {
    var goal = Math.max(1, Math.min(99, ($scope.data || {}).goal || 80));
    var angle = goal / 100 * 2 * Math.PI - Math.PI / 2;
    function point(radius, axis) { return 32 + radius * (axis === 'x' ? Math.cos(angle) : Math.sin(angle)); }
    return { x1: point(21, 'x'), y1: point(21, 'y'), x2: point(32, 'x'), y2: point(32, 'y') };
  };

  // one sentence: where the person stands
  c.headline = function() {
    var d = $scope.data || {};
    var goal = d.goal || 80;
    if (d.isAdmin) {
      var waiting = (d.team && d.team.kpi) ? d.team.kpi.review : 0;
      if (waiting) return waiting + ' submission' + (waiting === 1 ? ' is' : 's are') + ' waiting for your review.';
      var co = d.company || { covered: 0, total: 0, coveredPct: 0 };
      if (!co.total) return 'No service is in scope yet. Check the service_scope setting.';
      return co.coveredPct >= goal
        ? co.coveredPct + '% of services are covered by approved evidence.'
        : 'Only ' + co.coveredPct + '% of services are covered (goal ' + goal + '%). The follow-up lists show where to act.';
    }
    var follow = d.myFollow || {};
    var todo = (follow.need ? follow.need.count : 0) + (follow.stale ? follow.stale.count : 0);
    var soon = follow.expiring ? follow.expiring.count : 0;
    if (!d.mine || !d.mine.kpi || !d.mine.kpi.targets) return 'Nothing is assigned to you yet.';
    if (todo) return 'You have ' + todo + ' control' + (todo === 1 ? '' : 's') + ' to complete. One at a time is enough.';
    if (soon) return 'Everything is approved. ' + soon + ' will need a renewal soon.';
    return 'All clear: every control you own is approved.';
  };

  /* ---------- "Start here" ---------- */
  var nextCache = { data: null, value: null };

  // the most useful next step: rejected, then expired, then missing, then the next expiry
  function computeNext(d) {
    var follow = (d && d.myFollow) || {};
    var need = (follow.need && follow.need.items) || [];
    var stale = (follow.stale && follow.stale.items) || [];
    var soon = (follow.expiring && follow.expiring.items) || [];
    var rejected = need.filter(function(r) { return r.status === 'rejected'; });
    var missing = need.filter(function(r) { return r.status !== 'rejected'; });
    if (rejected.length) return { item: rejected[0], why: 'A reviewer asked for a better proof' };
    if (stale.length) return { item: stale[0], why: 'The previous proof has expired: renew it' };
    if (missing.length) return { item: missing[0], why: 'No evidence yet' };
    if (soon.length) return { item: soon[0], why: 'Expires in ' + soon[0].daysLeft + ' day' + (soon[0].daysLeft === 1 ? '' : 's') };
    return null;
  }

  c.nextAction = function() {
    var d = $scope.data;
    if (nextCache.data !== d) { nextCache.data = d; nextCache.value = computeNext(d); }
    return nextCache.value;
  };

  /* ---------- tabs and follow-up lists ---------- */

  // opens a tab and optionally a list in it (a list lives in the "To do" view of My services).
  // From a service page it goes back to the dashboard
  c.go = function(tab, listKey) {
    c.tab = tab;
    if (listKey) {
      c.sel[tab === 'follow' ? 'team' : 'mine'] = listKey;
      if (tab === 'mine') c.mineView = 'todo';
    }
    remember('tab', tab);
    remember('sel', c.sel);
    remember('mv', c.mineView);
    if (($scope.data || {}).screen === 'target') $window.location.href = '?id=cpm' + c.dbg();
  };

  // switches "My services" between the to-do list and the service cards
  c.setMine = function(view) {
    c.mineView = view;
    remember('mv', view);
  };

  c.ctx = function() { return c.tab === 'follow' ? 'team' : 'mine'; };
  c.showFollow = function() { return c.tab === 'follow' || (c.tab === 'mine' && c.mineView === 'todo'); };
  c.showCards = function() { return c.tab === 'all' || (c.tab === 'mine' && c.mineView === 'services'); };
  c.defs = function() { return c.ctx() === 'team' ? TEAM_LISTS : MINE_LISTS; };
  c.section = function() { return c.sel[c.ctx()]; };
  c.pick = function(key) {
    c.sel[c.ctx()] = key;
    remember('sel', c.sel);
  };

  function followSet() {
    var d = $scope.data || {};
    return (c.ctx() === 'team' ? d.follow : d.myFollow) || {};
  }

  c.countOf = function(key) {
    var part = followSet()[key];
    return part ? part.count : 0;
  };

  c.items = function() {
    var part = followSet()[c.section()];
    return part ? part.items : [];
  };

  c.more = function() {
    var part = followSet()[c.section()];
    return part ? Math.max(0, part.count - part.items.length) : 0;
  };

  c.emptyText = function() { return EMPTY_TEXT[c.section()] || 'Nothing to show.'; };

  // first visit only: selects the first list that has something in it
  if (!savedSel) {
    (function pickFirstFilled() {
      var d = $scope.data || {};
      [['team', d.follow, TEAM_LISTS], ['mine', d.myFollow, MINE_LISTS]].forEach(function(entry) {
        var set = entry[1] || {};
        for (var i = 0; i < entry[2].length; i++) {
          var key = entry[2][i].key;
          if (set[key] && set[key].count) { c.sel[entry[0]] = key; return; }
        }
      });
    })();
  }

  /* ---------- service cards: prepared once, filtered once, drawn page by page ---------- */
  var FIRST_PAGE = 12;   // cards drawn at once when a tab opens
  var PAGE = 24;         // then this many more each time
  c.shown = FIRST_PAGE;

  // changes each time the server data is replaced: keys the caches below
  var revState = { data: null, rev: 0 };
  function rev() {
    if (revState.data !== $scope.data) { revState.data = $scope.data; revState.rev++; }
    return revState.rev;
  }

  // adds what a card needs, once per row, so the card itself has nothing left to compute
  function prepare(row) {
    var good = row.approved - row.expiring;
    row.key = [row.id, row.approved, row.expiring, row.awaiting, row.rejected, row.expired, row.missing, row.risk, row.name].join('|');
    row.dash = row.coverage * 1.6336;
    row.pct = row.total ? row.coverage + '%' : '–';
    row.todo = row.missing + row.rejected + row.expired;
    row.g = { ok: good, watch: row.expiring, review: row.awaiting, action: row.rejected + row.expired, idle: row.missing };
    row.tip = good + ' approved · ' + row.expiring + ' expiring · ' + row.awaiting + ' in review · ' + row.rejected + ' rejected · ' + row.expired + ' stale · ' + row.missing + ' missing';
    row.hay = ((row.name || '') + ' ' + (row.kind || '')).toLowerCase();
  }

  function cardPart() {
    var d = $scope.data || {};
    return (c.tab === 'all' && d.team) ? d.team : d.mine;
  }

  // all the cards of the current tab
  c.rows = function() {
    var part = cardPart();
    if (!part || !part.rows) return [];
    if (!part.ready) { part.rows.forEach(prepare); part.ready = true; }
    return part.rows;
  };

  // were the cards cut at the maximum number?
  c.limited = function() {
    var part = cardPart();
    return !!(part && part.truncated);
  };

  function searchText() { return (c.q || '').trim().toLowerCase(); }

  // the cards that match the search and the chip (cached)
  var matchCache = { key: '', list: [] };
  c.matching = function() {
    var q = searchText();
    var key = rev() + '|' + c.tab + '|' + c.filter + '|' + q;
    if (matchCache.key !== key) {
      matchCache.key = key;
      matchCache.list = c.rows().filter(function(r) {
        return (!q || r.hay.indexOf(q) > -1) && (c.filter === 'all' || r.risk === c.filter);
      });
    }
    return matchCache.list;
  };

  // the cards drawn now (cached)
  var viewCache = { list: null, n: 0, out: [] };
  c.visibleRows = function() {
    var list = c.matching();
    if (viewCache.list !== list || viewCache.n !== c.shown) {
      viewCache.list = list;
      viewCache.n = c.shown;
      viewCache.out = list.slice(0, c.shown);
    }
    return viewCache.out;
  };

  c.cardsLeft = function() { return Math.max(0, c.matching().length - c.shown); };
  c.moreCards = function() { c.shown += PAGE; };

  // numbers on the chips (cached)
  var countCache = { key: '', value: {} };
  c.counts = function() {
    var q = searchText();
    var key = rev() + '|' + c.tab + '|' + q;
    if (countCache.key !== key) {
      var out = { all: 0, red: 0, yellow: 0, green: 0, not_assessed: 0 };
      c.rows().forEach(function(r) {
        if (q && r.hay.indexOf(q) < 0) return;
        out.all++;
        out[r.risk]++;
      });
      countCache.key = key;
      countCache.value = out;
    }
    return countCache.value;
  };

  // the scrolling list: more cards appear near its end
  var mainEl = null;
  var ticking = false;
  function onScroll() {
    if (ticking || !mainEl) return;
    ticking = true;
    $window.requestAnimationFrame(function() {
      ticking = false;
      if (mainEl.scrollTop + mainEl.clientHeight > mainEl.scrollHeight - 500) {
        $scope.$evalAsync(function() { if (c.cardsLeft() > 0) c.moreCards(); });
      }
    });
  }
  $timeout(function() {
    mainEl = document.querySelector('.cpm-main');
    if (mainEl) mainEl.addEventListener('scroll', onScroll, { passive: true });
  }, 100);

  // a new tab, view, chip or search: back to the top, a short first page, then it fills in
  $scope.$watchGroup(['c.tab', 'c.mineView', 'c.filter', 'c.q'], function() {
    c.shown = FIRST_PAGE;
    if (mainEl) mainEl.scrollTop = 0;
    $timeout(function() { if (c.shown === FIRST_PAGE) c.shown = PAGE; }, 60);
  });

  /* ---------- review decisions and "Refresh owners" ---------- */

  function review(evidence, payload) {
    c.working[evidence.id] = true;
    var done = function() { c.working[evidence.id] = false; };
    refresh(payload).then(done, done);
  }

  c.approve = function(evidence) {
    review(evidence, { action: 'approve', evidence: evidence.id });
  };

  c.reject = function(evidence) {
    review(evidence, { action: 'reject', evidence: evidence.id, comment: c.comment[evidence.id] });
  };

  c.syncNow = function() {
    c.syncing = true;
    var done = function() { c.syncing = false; };
    refresh({ action: 'sync' }).then(done, done);
  };

  /* ---------- opening a file ---------- */

  function downloadLink(href, name) {
    var link = document.createElement('a');
    link.href = href;
    link.download = name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // images open in the viewer, other files are downloaded
  c.open = function(evidenceId, file) {
    c.opening = file.id;
    ask({ action: 'file', evidence: evidenceId, attachment: file.id }).then(function(fresh) {
      c.opening = '';
      var result = fresh && fresh.file;
      if (!result || !result.ok) {
        c.toast = { type: 'error', text: (result && result.message) || 'The file could not be opened.' };
        return;
      }
      var href = 'data:' + result.type + ';base64,' + result.content;
      if (/^image\//.test(result.type)) c.preview = { name: result.name, src: href };
      else downloadLink(href, result.name);
    }, function() {
      c.opening = '';
      c.toast = { type: 'error', text: 'The file could not be opened.' };
    });
  };

  /* ---------- audit export ---------- */

  // quotes a value, and stops a spreadsheet from running it as a formula
  function csvCell(value) {
    var text = String(value === null || value === undefined ? '' : value);
    if (/^[=+\-@]/.test(text)) text = "'" + text;
    return '"' + text.replace(/"/g, '""') + '"';
  }

  c.exportAudit = function() {
    c.exporting = true;
    ask({ action: 'audit' }).then(function(fresh) {
      c.exporting = false;
      var rows = fresh && fresh.audit;
      if (!rows) { c.toast = { type: 'error', text: 'The audit export could not be prepared.' }; return; }
      var head = ['Evidence', 'Service or CI', 'Control reference', 'Control', 'Framework', 'Status', 'Submitted by', 'Submitted on',
                  'Reviewed by', 'Reviewed on', 'Valid until', 'Scope at approval', 'Files', 'Integrity'];
      var lines = [head.map(csvCell).join(',')];
      rows.forEach(function(r) {
        lines.push([r.number, r.target, r.ref, r.control, r.framework, r.status, r.submittedBy, r.submittedOn,
                    r.reviewedBy, r.reviewedOn, r.validUntil, r.scope, r.files, r.integrity].map(csvCell).join(','));
      });
      var blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8;' });
      var url = URL.createObjectURL(blob);
      downloadLink(url, 'compliance-audit-' + new Date().toISOString().substring(0, 10) + '.csv');
      $timeout(function() { URL.revokeObjectURL(url); }, 2000);
      c.toast = { type: 'ok', text: rows.length + ' approved proof' + (rows.length === 1 ? '' : 's') + ' exported.' };
    }, function() {
      c.exporting = false;
      c.toast = { type: 'error', text: 'The audit export failed.' };
    });
  };

  /* ---------- upload step 1: choosing files (nothing is sent) ---------- */

  // pasted screenshots are called "image.png": give them a real name
  function fileName(file) {
    var plain = file.name && file.name !== 'image.png';
    return plain ? file.name : 'screenshot-' + Date.now() + '-' + Math.floor(Math.random() * 1000) + '.png';
  }

  function humanSize(bytes) {
    return bytes > 1024 * 1024 ? (bytes / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
  }

  // a sentence when the file cannot be accepted, else ''
  function problemWith(file, list) {
    if (ALLOWED.indexOf(file.type) < 0) return 'Only images (PNG, JPG, GIF, WEBP) and PDF files are accepted.';
    if (file.size > MAX_BYTES) return 'This file is larger than 3 MB. Take a smaller screenshot, or save it as a JPG or PDF.';
    if (list.length >= MAX_FILES) return 'A submission can hold up to ' + MAX_FILES + ' files.';
    return '';
  }

  c.stage = function(mappingId, files) {
    var list = c.staged[mappingId] = c.staged[mappingId] || [];
    c.msg[mappingId] = '';
    c.toast = null;
    files.forEach(function(file) {
      var problem = problemWith(file, list);
      if (problem) { c.msg[mappingId] = problem; return; }
      var reader = new FileReader();
      reader.onload = function() {
        $timeout(function() {
          list.push({
            name: fileName(file), type: file.type, size: humanSize(file.size),
            isImage: /^image\//.test(file.type), dataUrl: reader.result,
            content: String(reader.result).split(',')[1] || ''
          });
        });
      };
      reader.onerror = function() { $timeout(function() { c.msg[mappingId] = 'This file could not be read.'; }); };
      reader.readAsDataURL(file);
    });
  };

  c.unstage = function(mappingId, index) {
    (c.staged[mappingId] || []).splice(index, 1);
  };

  c.clearStaged = function(mappingId) {
    c.staged[mappingId] = [];
    c.msg[mappingId] = '';
  };

  /* ---------- upload step 2: Submit (files go one by one into a draft, then the draft is submitted) ---------- */

  function fail(mappingId, text) {
    c.busy[mappingId] = false;
    c.msg[mappingId] = text;
    c.toast = { type: 'error', text: text };
  }

  // true when the server confirmed the step, else shows the problem
  function checkAnswer(mappingId, fresh) {
    if (!fresh) { fail(mappingId, 'The server did not answer. Look for "[CPM]" lines in System Log > All, and check that every Script Include is saved.'); return false; }
    if (fresh.error) { fail(mappingId, fresh.error); return false; }
    if (!fresh.upload) { fail(mappingId, 'The server did not confirm the request. The widget Server script may be out of date.'); return false; }
    if (!fresh.upload.ok) { fail(mappingId, fresh.upload.message); return false; }
    return true;
  }

  function sendFile(mappingId, list, index) {
    if (index >= list.length) return submit(mappingId);
    c.progress[mappingId] = 'Sending file ' + (index + 1) + ' of ' + list.length + '…';
    var file = list[index];
    ask({ action: 'addFile', mapping: mappingId, fileName: file.name, contentType: file.type, content: file.content, first: index === 0 })
      .then(function(fresh) {
        if (checkAnswer(mappingId, fresh)) sendFile(mappingId, list, index + 1);
      }, function() {
        fail(mappingId, 'The request failed. Check your connection, or that the files are smaller than 3 MB.');
      });
  }

  function submit(mappingId) {
    c.progress[mappingId] = 'Submitting…';
    refresh({ action: 'submit', mapping: mappingId }).then(function(fresh) {
      if (!checkAnswer(mappingId, fresh)) return;
      c.busy[mappingId] = false;
      c.staged[mappingId] = [];
      c.toast = { type: 'ok', text: 'Submitted. The compliance team will approve or reject your evidence.' };
    }, function() {
      fail(mappingId, 'The request failed. Please try again.');
    });
  }

  c.submit = function(ctl) {
    var list = c.staged[ctl.id] || [];
    if (!list.length || c.busy[ctl.id]) return;
    c.msg[ctl.id] = '';
    c.toast = null;
    c.busy[ctl.id] = true;
    sendFile(ctl.id, list, 0);
  };

  /* ---------- drag and drop, file picker, paste, Esc ---------- */

  function hasFiles(e) {
    var types = (e.dataTransfer && e.dataTransfer.types) || [];
    return Array.prototype.indexOf.call(types, 'Files') > -1;
  }

  function zoneOf(e) {
    return e.target && e.target.closest ? e.target.closest('.cpm-drop') : null;
  }

  function mappingOf(zone) {
    var input = zone.querySelector('.cpm-picker');
    return input ? input.getAttribute('data-mapping') : '';
  }

  function choose(mappingId, fileList) {
    var files = Array.prototype.slice.call(fileList);
    $scope.$apply(function() { c.stage(mappingId, files); });
  }

  // while dragging: highlight the zone, and stop the browser opening a file dropped elsewhere
  function onDrag(e) {
    if (!hasFiles(e) || !document.querySelector('.cpm')) return;
    var zone = zoneOf(e);
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = zone ? 'copy' : 'none';
    if (zone) zone.classList.add('over');
  }

  function onLeave(e) {
    var zone = zoneOf(e);
    if (zone) zone.classList.remove('over');
  }

  function onDrop(e) {
    if (!hasFiles(e) || !document.querySelector('.cpm')) return;
    e.preventDefault();
    var zone = zoneOf(e);
    if (!zone) return;
    zone.classList.remove('over');
    choose(mappingOf(zone), e.dataTransfer.files);
  }

  function onChange(e) {
    if (!e.target.classList || !e.target.classList.contains('cpm-picker')) return;
    var mappingId = e.target.getAttribute('data-mapping');
    var files = Array.prototype.slice.call(e.target.files);
    e.target.value = '';
    $scope.$apply(function() { c.stage(mappingId, files); });
  }

  // Ctrl+V while the mouse is over a control card
  function onPaste(e) {
    if (!e.clipboardData || !e.clipboardData.files.length) return;
    var zone = document.querySelector('.cpm .cpm-ctl:hover .cpm-drop');
    if (!zone) return;
    e.preventDefault();
    choose(mappingOf(zone), e.clipboardData.files);
  }

  // Esc closes the image viewer
  function onKey(e) {
    if (e.key === 'Escape' && c.preview) $scope.$apply(function() { c.preview = null; });
  }

  document.addEventListener('dragenter', onDrag);
  document.addEventListener('dragover', onDrag);
  document.addEventListener('dragleave', onLeave);
  document.addEventListener('drop', onDrop);
  document.addEventListener('change', onChange);
  document.addEventListener('paste', onPaste);
  document.addEventListener('keydown', onKey);
  $scope.$on('$destroy', function() {
    document.removeEventListener('dragenter', onDrag);
    document.removeEventListener('dragover', onDrag);
    document.removeEventListener('dragleave', onLeave);
    document.removeEventListener('drop', onDrop);
    document.removeEventListener('change', onChange);
    document.removeEventListener('paste', onPaste);
    document.removeEventListener('keydown', onKey);
    if (mainEl) mainEl.removeEventListener('scroll', onScroll);
    angular.element($window).off('resize', fit);
  });
};

sp_widget.css:
/* palette: navy = trust, teal = done, amber = watch the date, coral = act, blue = in review, slate = not started */
.cpm {
  --ink: #0f1b2d; --muted: #5b6b82; --bg: #f4f7fb; --card: #ffffff; --line: #e3e9f2;
  --brand: #17408b; --brand-dark: #0b2a5b;
  --ok: #0f9d75;     --ok-soft: #e5f6f0;     --ok-ink: #0a6b50;
  --watch: #e8a317;  --watch-soft: #fdf3dc;  --watch-ink: #8a5a00;
  --action: #df5a49; --action-soft: #fdecea; --action-ink: #9b2c20;
  --review: #3b6fd4; --review-soft: #e8effc; --review-ink: #234aa0;
  --idle: #8a97ab;   --idle-soft: #eef1f6;   --idle-ink: #4c5b72;
  --shadow: 0 2px 10px rgba(15,27,45,.05); --shadow-lg: 0 16px 36px rgba(15,27,45,.14);
  color: var(--ink);
}
.cpm * { box-sizing: border-box; }
.cpm a { color: inherit; }
.cpm a:hover { text-decoration: none; }
.cpm button:focus-visible, .cpm a:focus-visible, .cpm input:focus-visible, .cpm [tabindex]:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }
@keyframes cpm-drop { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes cpm-slide { from { transform: translateX(-100%); } to { transform: translateX(260%); } }

/* alerts above the dashboard */
.cpm-alert { background: var(--action-soft); color: var(--action-ink); padding: 14px 18px; border-radius: 14px; margin-bottom: 12px; }
.cpm-alert ul { margin: 6px 0 0 18px; }

/* the frame fills the window under its top edge and uses the whole window width (set by the script) */
.cpm-cq { container-type: inline-size; }
.cpm-frame { position: relative; display: flex; flex-direction: column; gap: 8px; min-height: 560px; padding: 16px; overflow: hidden;
  border-radius: 26px; background: linear-gradient(180deg, #f6f9fd, #eef3fa); }
.cpm-frame.bleed { border-radius: 0; padding: 18px 22px 8px; }
.cpm-foot { flex: none; text-align: right; font-size: 11px; color: var(--muted); }

/* three columns: guide | middle | stats. The side columns run the full height */
.cpm-shell { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: 272px minmax(0, 1fr) 330px; grid-template-rows: minmax(0, 1fr); gap: 18px; }
.cpm-shell.no-cat { grid-template-columns: minmax(0, 1fr) 330px; }
.cpm-catalog, .cpm-main, .cpm-side { min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: #c3cddd transparent; }
.cpm-center { position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 0; min-width: 0; }
.cpm-main { flex: 1 1 auto; padding: 2px 8px 28px 2px; }   /* the only scrolling part of the middle column */
.cpm-side { display: flex; flex-direction: column; gap: 14px; padding: 2px 4px 20px 2px; }
.cpm-catalog { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 16px; box-shadow: var(--shadow); }

/* medium containers: the guide slides over the middle column */
@container (max-width: 1099px) {
  .cpm-shell, .cpm-shell.no-cat { grid-template-columns: minmax(0, 1fr) 300px; position: relative; }
  .cpm-catalog { position: absolute; left: 0; top: 0; bottom: 0; width: 300px; z-index: 30; box-shadow: var(--shadow-lg); }
}
/* small containers: one column, the page scrolls normally */
@container (max-width: 759px) {
  .cpm-frame { height: auto !important; min-height: 0; }
  .cpm-hero { flex-wrap: wrap; }
  .cpm-hero-actions { flex-direction: row; flex-wrap: wrap; }
  .cpm-shell, .cpm-shell.no-cat { display: flex; flex-direction: column; }
  .cpm-catalog, .cpm-main, .cpm-side { overflow: visible; position: static; width: auto; box-shadow: none; }
  .cpm-main { flex: none; }
  .cpm-center { order: 1; } .cpm-side { order: 2; } .cpm-catalog { order: 3; }
}

/* messages: a strip above the banner (the banner moves down while one is shown) */
.cpm-notes { flex: none; display: flex; flex-direction: column; gap: 6px; }
.cpm-toast, .cpm-notice { cursor: pointer; padding: 9px 16px; border-radius: 12px; font-size: 13px; animation: cpm-drop .25s ease both; }
.cpm-toast.ok, .cpm-notice.ok { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-toast.error, .cpm-notice.error { background: var(--action-soft); color: var(--action-ink); }
.cpm-x { float: right; font-weight: 700; margin-left: 12px; }
.cpm-loading { position: absolute; left: 0; right: 0; top: 0; height: 3px; overflow: hidden; z-index: 70; background: rgba(23,64,139,.15); border-radius: 3px; }
.cpm-loading::after { content: ''; position: absolute; top: 0; bottom: 0; width: 40%; background: var(--brand); animation: cpm-slide 1s ease-in-out infinite; }

/* banner: the width of the middle column, never scrolls */
.cpm-hero { position: relative; flex: none; overflow: hidden; display: flex; align-items: center; gap: 20px; padding: 16px 22px;
  border-radius: 22px; color: #fff; box-shadow: 0 14px 34px rgba(11,42,91,.24);
  background: linear-gradient(135deg, #0b2a5b 0%, #17408b 55%, #0f7c8a 100%); }
.cpm-hero::before { content: ''; position: absolute; right: -50px; top: -80px; width: 240px; height: 240px; border-radius: 50%; background: rgba(255,255,255,.07); }
.cpm-hero::after { content: ''; position: absolute; left: 40%; bottom: -140px; width: 260px; height: 260px; border-radius: 50%; background: rgba(94,234,212,.08); }
.cpm-hero > * { position: relative; z-index: 1; }
.cpm-hero-ring { position: relative; width: 88px; height: 88px; flex: none; }
.cpm-hero-ring svg { width: 100%; height: 100%; overflow: visible; }
.cpm-hero-label { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.cpm-hero-label b { font-size: 20px; line-height: 1; }
.cpm-hero-label span { font-size: 9px; opacity: .75; }
.cpm-hero .track { fill: none; stroke: rgba(255,255,255,.2); stroke-width: 7; }
.cpm-hero .bar { fill: none; stroke: #5eead4; stroke-width: 7; stroke-linecap: round; transition: stroke-dasharray .9s ease; }
.cpm-hero .goal-tick { stroke: #fff; stroke-width: 1.6; stroke-linecap: round; opacity: .9; }
.cpm-hero-text { flex: 1; min-width: 0; }
.cpm-hero h2 { margin: 2px 0 0; font-size: 24px; color: #fff; }
.cpm-headline { margin: 3px 0 8px; font-size: 14px; opacity: .95; }
.cpm-hchip { display: inline-block; font-size: 11px; padding: 3px 11px; border-radius: 999px; background: rgba(255,255,255,.16); }
.cpm-eyebrow { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; opacity: .75; }
.cpm-eyebrow.dark { color: var(--brand); opacity: 1; }
.cpm-hero-actions { display: flex; flex-direction: column; gap: 6px; align-items: stretch; flex: none; }
.cpm-hbtn { border: 1px solid rgba(255,255,255,.35); background: rgba(255,255,255,.12); color: #fff; border-radius: 999px; padding: 6px 14px;
  font-size: 12px; font-weight: 600; cursor: pointer; white-space: nowrap; }
.cpm-hbtn:hover { background: rgba(255,255,255,.24); }
.cpm-hbtn[disabled] { opacity: .6; cursor: default; }

/* fixed bars under the banner: tabs, filters and search never scroll */
.cpm-bar { flex: none; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.cpm-tools { padding: 0 2px; }
.cpm-tools-title { font-size: 12px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; margin-right: 4px; }
.cpm-tabs { display: flex; gap: 6px; flex-wrap: wrap; }
.cpm-tabs button { border: 0; background: transparent; padding: 8px 16px; font-weight: 600; color: var(--muted); border-radius: 999px; cursor: pointer; }
.cpm-tabs button:hover { background: var(--idle-soft); }
.cpm-tabs button.active { background: var(--brand); color: #fff; }
.cpm-subtabs { display: inline-flex; gap: 4px; padding: 3px; background: var(--idle-soft); border-radius: 999px; margin-left: auto; }
.cpm-bar > .cpm-subtabs:first-child { margin-left: 0; }
.cpm-subtabs button { border: 0; background: transparent; padding: 6px 14px; border-radius: 999px; font-weight: 600; font-size: 13px; color: var(--muted); cursor: pointer; }
.cpm-subtabs button.active { background: var(--card); color: var(--brand); box-shadow: var(--shadow); }
.cpm-count { display: inline-block; min-width: 22px; text-align: center; background: var(--review); color: #fff; border-radius: 999px; font-size: 11px; padding: 1px 7px; margin-left: 4px; }
.cpm-count.idle { background: var(--idle); }
.cpm-tabs button.active .cpm-count { background: #fff; color: var(--brand); }

/* chips and search */
.cpm-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.cpm-chips button { border: 1px solid #cbd5e1; background: var(--card); border-radius: 999px; padding: 6px 14px; font-size: 13px; cursor: pointer; }
.cpm-chips button.active { background: var(--brand); border-color: var(--brand); color: #fff; }
.cpm-searchbar { display: flex; gap: 8px; align-items: center; margin-left: auto; }
.cpm-search { border: 1px solid #cbd5e1; border-radius: 12px; padding: 8px 14px; min-width: 220px; background: #fff; }

/* stats guide */
.cpm-cat-head h4 { margin: 0 0 2px; font-size: 16px; }
.cpm-cat-head p { margin: 0 0 10px; font-size: 12px; color: var(--muted); }
.cpm-cat-search { width: 100%; border: 1px solid #cbd5e1; border-radius: 12px; padding: 8px 12px; font-size: 13px; background: #fff; }
.cpm-cat-group h5 { margin: 16px 0 6px; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }
.cpm-cat-item { display: flex; gap: 10px; padding: 9px 10px; border-radius: 12px; margin-bottom: 4px; }
.cpm-cat-item.go { cursor: pointer; }
.cpm-cat-item.go:hover { background: var(--bg); }
.cpm-cat-item b { display: block; font-size: 13px; }
.cpm-cat-item p { margin: 2px 0 0; font-size: 12px; color: var(--muted); line-height: 1.4; }
.cpm-cat-item small { display: block; margin-top: 3px; font-size: 11px; color: var(--idle-ink); line-height: 1.4; }
.cpm-dot { width: 10px; height: 10px; border-radius: 50%; flex: none; margin-top: 4px; background: var(--idle); }
.cpm-dot.ok { background: var(--ok); } .cpm-dot.watch { background: var(--watch); } .cpm-dot.action { background: var(--action); }
.cpm-dot.review { background: var(--review); } .cpm-dot.brand { background: var(--brand); }

/* right column */
.cpm-side-card { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 16px 18px; box-shadow: var(--shadow); }
.cpm-side-card h4 { margin: 0 0 12px; font-size: 15px; }
.cpm-side-card h4 small { color: var(--muted); font-weight: 400; margin-left: 6px; }
.cpm-kpis { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.cpm-kpi { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 12px 12px 10px 14px; }
button.cpm-kpi { font: inherit; color: inherit; text-align: left; width: 100%; display: block; }
.cpm-kpi::before { content: ''; position: absolute; left: 0; top: 12px; bottom: 12px; width: 4px; border-radius: 0 4px 4px 0; background: var(--brand); }
.cpm-kpi i { font-style: normal; position: absolute; right: 8px; top: 8px; width: 24px; height: 24px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; font-size: 12px; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-kpi b { display: block; font-size: 22px; line-height: 1.1; }
.cpm-kpi span { font-size: 11px; color: var(--muted); }
.cpm-kpi.ok::before { background: var(--ok); }         .cpm-kpi.ok i { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-kpi.watch::before { background: var(--watch); }   .cpm-kpi.watch i { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-kpi.action::before { background: var(--action); } .cpm-kpi.action i { background: var(--action-soft); color: var(--action-ink); }
.cpm-kpi.review::before { background: var(--review); } .cpm-kpi.review i { background: var(--review-soft); color: var(--review-ink); }
.cpm-kpi.idle::before { background: var(--idle); }
.cpm-kpi.clickable { cursor: pointer; transition: transform .15s, box-shadow .15s; }
.cpm-kpi.clickable:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }

/* controls by status */
.cpm-donut-wrap { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.cpm-donut { position: relative; width: 132px; height: 132px; flex: none; }
.cpm-donut svg { width: 100%; height: 100%; }
.cpm-donut .track { fill: none; stroke: var(--line); stroke-width: 7; }
.cpm-donut .seg { fill: none; stroke-width: 7; transition: stroke-dasharray .6s; }
.cpm-donut .seg.ok { stroke: var(--ok); } .cpm-donut .seg.watch { stroke: var(--watch); } .cpm-donut .seg.review { stroke: var(--review); }
.cpm-donut .seg.action { stroke: var(--action); } .cpm-donut .seg.idle { stroke: var(--idle); }
.cpm-donut-label { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.cpm-donut-label b { font-size: 24px; line-height: 1; }
.cpm-donut-label span { font-size: 11px; color: var(--muted); }
.cpm-legend { width: 100%; }
.cpm-legend-row { display: grid; grid-template-columns: 14px 1fr auto 42px; gap: 8px; align-items: center; padding: 5px 0; border-bottom: 1px solid #f1f5f9; font-size: 13px; }
.cpm-legend-row .cpm-dot { margin-top: 0; }
.cpm-legend-row em { font-style: normal; color: var(--muted); text-align: right; font-size: 12px; }

/* frameworks and approvals */
.cpm-fw { margin-bottom: 10px; }
.cpm-fw-line { display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 4px; }
.cpm-fw-line small { display: block; font-weight: 400; opacity: .7; font-size: 12px; }
.cpm-apr { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px; }
.cpm-apr div { background: var(--bg); border-radius: 12px; padding: 10px 12px; }
.cpm-apr b { display: block; font-size: 20px; line-height: 1.2; }
.cpm-apr span { font-size: 11px; color: var(--muted); }
.cpm-apr-foot { margin: 8px 0 0; }

/* empty states: "good" ones celebrate */
.cpm-empty { text-align: center; color: var(--muted); padding: 28px; background: var(--card); border: 1px dashed var(--line); border-radius: 16px; margin-bottom: 14px; }
.cpm-empty.good { background: var(--ok-soft); border-color: transparent; color: var(--ok-ink); font-weight: 600; }

/* "Start here" */
.cpm-next { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 18px 22px; margin-bottom: 16px;
  border-radius: 18px; background: linear-gradient(135deg, #eef3ff, #e5f6f0); border: 1px solid #d5e2f7; }
.cpm-next.clickable { cursor: pointer; transition: box-shadow .15s; }
.cpm-next.clickable:hover { box-shadow: var(--shadow-lg); }
.cpm-next h4 { margin: 2px 0 2px; font-size: 17px; }
.cpm-next p { margin: 0; color: var(--muted); font-size: 13px; }

/* review inbox and buttons */
.cpm-review { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--review); border-radius: 18px; padding: 16px 20px; margin-bottom: 12px; box-shadow: var(--shadow); }
.cpm-review-top { display: flex; justify-content: space-between; gap: 12px; }
.cpm-review-title { font-weight: 600; font-size: 16px; }
.cpm-age { font-size: 12px; padding: 3px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); align-self: flex-start; white-space: nowrap; }
.cpm-age.late { background: var(--action-soft); color: var(--action-ink); }
.cpm-actions { display: flex; gap: 10px; margin-top: 12px; }
.cpm-btn { border: 0; border-radius: 12px; padding: 9px 20px; font-weight: 600; color: #fff; cursor: pointer; text-decoration: none; display: inline-block; }
.cpm-btn.ok { background: var(--ok); } .cpm-btn.bad { background: var(--action); } .cpm-btn.brand { background: var(--brand); }
.cpm-btn.plain { background: var(--idle-soft); color: var(--ink); }
.cpm-btn[disabled] { opacity: .5; cursor: default; }
.cpm-rejectbox { margin-top: 10px; }
.cpm-rejectbox textarea { width: 100%; border: 1px solid #cbd5e1; border-radius: 12px; padding: 8px 12px; margin-bottom: 8px; }

/* panels */
.cpm-panel { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 18px 22px; margin-bottom: 16px; box-shadow: var(--shadow); }
.cpm-panel h4 { margin: 0 0 12px; font-size: 15px; }
.cpm-rollup { background: var(--bg); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0 12px; }

/* tables */
.cpm-tablewrap { overflow-x: auto; margin-top: 4px; }
.cpm-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.cpm-table th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 600; padding: 8px 10px; border-bottom: 1px solid var(--line); white-space: nowrap; }
.cpm-table td { padding: 10px; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
.cpm-table tr:hover td { background: #f8fafc; }
.cpm-table tr.clickable { cursor: pointer; }
.cpm-table a { color: var(--brand); font-weight: 600; }
.cpm-mini { min-width: 160px; }
.cpm-mini small { color: var(--muted); font-size: 11px; }
.cpm-status { font-size: 12px; font-weight: 600; padding: 2px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); white-space: nowrap; }
.cpm-status.st-missing, .cpm-status.st-rejected, .cpm-status.st-expired, .cpm-status.st-uncovered { background: var(--action-soft); color: var(--action-ink); }
.cpm-status.st-approved { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-status.st-expiring { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-status.st-awaiting { background: var(--review-soft); color: var(--review-ink); }
.cpm-flag { display: inline-block; font-size: 12px; font-weight: 700; padding: 2px 10px; border-radius: 999px; background: var(--watch-soft); color: var(--watch-ink); white-space: nowrap; }

/* service cards */
.cpm-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; margin: 4px 0 14px; }
.cpm-more { text-align: center; margin: 4px 0 26px; }
.cpm-card { display: block; background: var(--card); border: 1px solid var(--line); border-top: 4px solid var(--idle); border-radius: 18px; padding: 16px; box-shadow: var(--shadow); transition: transform .15s, box-shadow .15s; }
.cpm-card.risk-green { border-top-color: var(--ok); } .cpm-card.risk-yellow { border-top-color: var(--watch); } .cpm-card.risk-red { border-top-color: var(--action); }
.cpm-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.cpm-card-head { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.cpm-card-title { font-weight: 600; font-size: 15px; margin-bottom: 4px; }
.cpm-card-foot { display: flex; justify-content: space-between; font-size: 12px; color: var(--muted); margin-top: 10px; }
.cpm-kind { color: var(--muted); font-size: 11px; margin-left: 6px; }

/* rings, colored by risk */
.cpm-ring { width: 60px; height: 60px; flex: none; }
.cpm-ring.big { width: 84px; height: 84px; }
.cpm-ring .track { fill: none; stroke: var(--line); stroke-width: 7; }
.cpm-ring .bar { fill: none; stroke-width: 7; stroke-linecap: round; }
.cpm-ring text { font-size: 15px; font-weight: 700; fill: var(--ink); }
.risk-green .bar { stroke: var(--ok); } .risk-yellow .bar { stroke: var(--watch); }
.risk-red .bar { stroke: var(--action); } .risk-not_assessed .bar { stroke: var(--idle); }
.cpm-pill { font-size: 11px; font-weight: 600; padding: 2px 10px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-pill.r-green { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-pill.r-yellow { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-pill.r-red { background: var(--action-soft); color: var(--action-ink); }

/* split bar */
.cpm-seg { display: flex; height: 8px; border-radius: 999px; overflow: hidden; background: var(--line); }
.cpm-seg i { display: block; flex: 0 1 0; }
.cpm-seg .ok { background: var(--ok); } .cpm-seg .watch { background: var(--watch); } .cpm-seg .review { background: var(--review); }
.cpm-seg .action { background: var(--action); } .cpm-seg .idle { background: var(--idle); }

/* page of one CI or service */
.cpm-back { display: inline-block; font-size: 13px; color: var(--brand); font-weight: 600; margin-bottom: 4px; }
.cpm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; background: var(--card); border: 1px solid var(--line);
  border-radius: 20px; padding: 18px 22px; margin: 8px 0 16px; box-shadow: var(--shadow); }
.cpm-head-main { flex: 1; min-width: 200px; }
.cpm-head h3 { margin: 0 0 2px; }
.cpm-sub { font-size: 12px; color: var(--muted); margin-bottom: 8px; }
.cpm-partof { font-size: 12px; margin-bottom: 8px; }
.cpm-partof a { color: var(--brand); font-weight: 600; }
.cpm-head-stats { display: flex; gap: 20px; text-align: center; }
.cpm-head-stats b { display: block; font-size: 22px; line-height: 1.1; }
.cpm-head-stats span { font-size: 11px; color: var(--muted); }
.cpm-ctl { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--idle); border-radius: 18px; padding: 16px 20px; margin-bottom: 12px; box-shadow: var(--shadow); }
.cpm-ctl.st-approved { border-left-color: var(--ok); } .cpm-ctl.st-expiring { border-left-color: var(--watch); }
.cpm-ctl.st-awaiting { border-left-color: var(--review); }
.cpm-ctl.st-rejected, .cpm-ctl.st-expired { border-left-color: var(--action); }
.cpm-ctl-top { display: flex; justify-content: space-between; gap: 12px; }
.cpm-state { font-size: 12px; font-weight: 600; white-space: nowrap; padding: 3px 12px; border-radius: 999px; height: fit-content; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-state.st-approved { background: var(--ok-soft); color: var(--ok-ink); }
.cpm-state.st-expiring { background: var(--watch-soft); color: var(--watch-ink); }
.cpm-state.st-awaiting { background: var(--review-soft); color: var(--review-ink); }
.cpm-state.st-rejected, .cpm-state.st-expired { background: var(--action-soft); color: var(--action-ink); }
.cpm-text { font-size: 13px; margin: 8px 0 4px; }
.cpm-guide { font-size: 13px; color: var(--muted); margin: 6px 0; }
.cpm-reject { background: var(--action-soft); color: var(--action-ink); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-wait { background: var(--review-soft); color: var(--review-ink); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-why { background: var(--bg); border: 1px dashed var(--line); color: var(--muted); border-radius: 12px; padding: 10px 14px; font-size: 13px; margin: 8px 0; }
.cpm-debug { font: 11px/1.4 monospace; background: #fefce8; color: #854d0e; border-radius: 8px; padding: 6px 10px; margin-top: 6px; }

/* drop zone and chosen files */
.cpm-drop { display: block; margin: 8px 0; padding: 16px; border: 2px dashed #b8c4d8; border-radius: 14px; text-align: center;
  font-size: 13px; color: #475569; cursor: pointer; background: #fbfcfe; }
.cpm-drop:hover, .cpm-drop:focus, .cpm-drop.over { border-color: var(--brand); background: var(--review-soft); outline: none; }
.cpm-staged { background: var(--bg); border: 1px solid var(--line); border-radius: 14px; padding: 12px 14px; margin: 8px 0; }
.cpm-staged-title { font-size: 13px; font-weight: 600; margin-bottom: 8px; }
.cpm-staged-list { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.cpm-chip { display: flex; align-items: center; gap: 8px; background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 6px 8px; font-size: 12px; max-width: 280px; }
.cpm-chip img, .cpm-chip-pdf { width: 46px; height: 36px; object-fit: cover; border-radius: 6px; flex: none; }
.cpm-chip-pdf { display: flex; align-items: center; justify-content: center; background: var(--idle-soft); font-weight: 700; }
.cpm-chip b { display: block; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cpm-chip small { color: var(--muted); }
.cpm-chip button { border: 0; background: transparent; font-size: 18px; line-height: 1; color: #64748b; cursor: pointer; }
.cpm-staged-actions { display: flex; gap: 10px; }
.cpm-error { color: var(--action-ink); font-size: 13px; margin: 6px 0; }

/* history, files and image viewer */
.cpm-ev { border-top: 1px solid #f1f5f9; padding: 8px 0; font-size: 13px; }
.cpm-tag { font-size: 11px; font-weight: 500; padding: 1px 8px; border-radius: 999px; background: var(--idle-soft); color: var(--idle-ink); }
.cpm-tag.st-approved { background: var(--ok-soft); color: var(--ok-ink); } .cpm-tag.st-pending { background: var(--review-soft); color: var(--review-ink); }
.cpm-tag.st-rejected { background: var(--action-soft); color: var(--action-ink); }
.cpm-seal { font-size: 11px; margin-left: 8px; color: var(--ok-ink); font-weight: 600; }
.cpm-seal.bad { color: var(--action-ink); }
.cpm-scope { margin: 6px 0; font-size: 12px; color: var(--muted); }
.cpm-scope summary { cursor: pointer; color: var(--brand); font-weight: 600; }
.cpm-scope p { margin: 6px 0 0; }
.cpm-files { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0; }
.cpm-filebtn { border: 1px solid #cbd5e1; background: #fff; border-radius: 999px; padding: 4px 12px; font-size: 12px; cursor: pointer; max-width: 320px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cpm-filebtn:hover { border-color: var(--brand); color: var(--brand); }
.cpm-lightbox { position: fixed; inset: 0; background: rgba(11,42,91,.88); z-index: 2000; display: flex; flex-direction: column;
  align-items: center; justify-content: center; color: #fff; font-size: 13px; cursor: pointer; padding: 24px; }
.cpm-lightbox img { max-width: 92vw; max-height: 82vh; border-radius: 12px; background: #fff; margin-bottom: 10px; }

@media (prefers-reduced-motion: reduce) {
  .cpm * { animation: none !important; transition: none !important; }
}

sp_widget.script:
// routes the request: actions first, then the screen. Counting is done by CPMStats
(function() {
  var LIST_LIMIT = 200;    // rows per follow-up list (the real total is shown)
  var AUDIT_LIMIT = 2000;  // rows in the audit export
  var access, stats, review, evidence, msg, util, K;

  data.serverBuild = '';
  data.error = '';
  data.notice = null;
  data.upload = null;
  data.file = null;
  data.audit = null;
  data.health = [];

  try {
    K = new CPMConst();
    msg = new CPMMsg();
    util = new CPMUtil();
    access = new CPMAccess();
    stats = new CPMStats();
    review = new CPMReview();
    evidence = new CPMEvidence();
    data.serverBuild = stats.VERSION;
    route();
  } catch (e) {
    gs.error('[CPM] widget failed: ' + e.message);
    data.error = failureText(e);
  }

  // generic text for users, with the detail for the compliance team
  function failureText(e) {
    var generic = 'Something went wrong. Please try again, or contact the compliance team.';
    var isTeam = false;
    try {
      generic = msg.get('cpm.err.unexpected');
      isTeam = access.isAdmin();
    } catch (ignore) {
      isTeam = gs.hasRole('admin');
    }
    return isTeam ? generic + ' (' + e.message + '). Look for "[CPM]" in System Log > All, and check that all Script Includes are saved in this application.' : generic;
  }

  function route() {
    var targetId = param('target');
    if (!K.isId(targetId)) targetId = '';
    data.params = { target: targetId, debug: param('debug') };
    data.isAdmin = access.isAdmin();
    data.me = gs.getUserID();
    data.rules = { goal: util.intProp('green_min', 80), yellow: util.intProp('yellow_min', 50), warning: util.intProp('warning_days', 30),
                   maxMb: util.intProp('max_file_mb', 3), maxFiles: K.MAX_FILES };
    data.goal = data.rules.goal;
    data.debug = data.isAdmin && data.params.debug == '1';

    var action = input && input.action;

    // light actions: answer at once, no screen
    if (action == 'addFile') {
      var file = {
        name: String(input.fileName || '').replace(/[\\\/]/g, '_').substring(0, 100),
        type: String(input.contentType || '').toLowerCase()
      };
      data.upload = evidence.addFile(String(input.mapping || ''), file, String(input.content || ''), String(input.first) == 'true');
      return;
    }
    if (action == 'file') {
      data.file = evidence.getFile(String(input.evidence || ''), String(input.attachment || ''));
      return;
    }
    if (action == 'audit') {
      data.audit = access.isAdmin() ? stats.audit(AUDIT_LIMIT) : [];
      return;
    }

    // actions that change something: the screen is reloaded afterwards
    if (action == 'submit') data.upload = evidence.submit(String(input.mapping || ''));
    if (action == 'approve') report(review.approve(String(input.evidence || '')), msg.get('cpm.ok.approved'));
    if (action == 'reject') report(review.reject(String(input.evidence || ''), String(input.comment || '')), msg.get('cpm.ok.rejected'));
    if (action == 'sync' && access.isAdmin()) report('', msg.get('cpm.ok.synced', [new CPMMapping().refreshOwners()]));

    if (data.isAdmin) data.health = util.healthProblems();
    if (targetId) loadTarget(targetId);
    else loadHome();
  }

  function param(name) {
    if (input && input[name] !== undefined && input[name] !== null) return String(input[name]);
    return $sp.getParameter(name) || '';
  }

  function report(error, okText) {
    data.notice = error ? { type: 'error', text: error } : { type: 'ok', text: okText };
  }

  // the numbers of the banner and of the right column, on every screen. "light" = counts only, no lists
  function loadSide(light) {
    data.mine = stats.posture(access.ownedTargetIds(), access.userId, light);
    data.myFollow = light ? stats.followCounts(access.userId) : stats.followUp(access.userId, LIST_LIMIT);
    data.approvals = stats.approvals(data.isAdmin ? '' : access.userId);
    if (!data.isAdmin) return;

    data.team = stats.posture(null, '', light);
    data.team.kpi.review = stats.count(K.TABLE.EVIDENCE, 'status=' + K.STATUS.PENDING);
    data.company = stats.serviceCoverage();
    data.frameworks = stats.frameworks();
    data.follow = light ? stats.followCounts('') : stats.followUp(null, LIST_LIMIT);
    if (!light) data.inbox = stats.inbox(20);
  }

  function loadHome() {
    data.screen = 'home';
    loadSide(false);
  }

  function loadTarget(id) {
    data.screen = 'target';
    if (!access.canViewTarget(id)) { data.error = msg.get('cpm.err.no_access'); return; }
    data.target = stats.detail(id);
    if (!data.target) { data.error = msg.get('cpm.err.not_found'); return; }
    loadSide(true);
  }
})();
